'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `with` method', function test( t ) {
	var arr = new Float64Array( 2 );
	t.strictEqual( hasProp( arr, 'with' ), true, 'has property' );
	t.strictEqual( isFunction( arr.with ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.with.call( value, 0, 1.0 );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not in bounds', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float64Array( 10 );

	values = [
		-11,
		-12,
		11,
		12
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), RangeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.with( value, 1.0 );
		};
	}
});

tape( 'the method does not change the array length', function test( t ) {
	var arr;
	var out;

	arr = new Float64Array( 10 );
	out = arr.with( 5, 1.0 );

	t.strictEqual( out.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the method returns a new typed array with the element at a provided index replaced with a provided value', function test( t ) {
	var arr;
	var out;

	arr = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	out = arr.with( 1, 5.0 );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.notEqual( out, arr, 'returns new instance' );
	t.strictEqual( out[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 5.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 3.0, 'returns expected value' );
	t.strictEqual( out[ 3 ], 4.0, 'returns expected value' );
	t.end();
});

tape( 'the method supports negative indices', function test( t ) {
	var arr;
	var out;

	arr = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = arr.with( -1, 5.0 );

	t.strictEqual( out instanceof Float64Array, true, 'returns expected value' );
	t.strictEqual( out[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 5.0, 'returns expected value' );
	t.end();
});

tape( 'the method does not mutate the original array', function test( t ) {
	var arr;
	var out;

	arr = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = arr.with( 1, 5.0 );

	t.strictEqual( arr[ 0 ], 1.0, 'original is unchanged' );
	t.strictEqual( arr[ 1 ], 2.0, 'original is unchanged' );
	t.strictEqual( arr[ 2 ], 3.0, 'original is unchanged' );
	t.strictEqual( out[ 1 ], 5.0, 'returns expected value' );
	t.end();
});
